package com.himeros.messaging;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="conversations")class Conversation{@Id private UUID id;@Column(name="match_id",nullable=false,unique=true)private UUID matchId;@Column(name="user_a",nullable=false)private UUID userA;@Column(name="user_b",nullable=false)private UUID userB;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="last_message_at")private Instant lastMessageAt;protected Conversation(){}Conversation(UUID matchId,UUID a,UUID b){id=UUID.randomUUID();this.matchId=matchId;userA=a;userB=b;createdAt=Instant.now();}UUID id(){return id;}UUID matchId(){return matchId;}UUID a(){return userA;}UUID b(){return userB;}Instant created(){return createdAt;}Instant last(){return lastMessageAt;}boolean contains(UUID u){return userA.equals(u)||userB.equals(u);}void touch(Instant at){lastMessageAt=at;}}
